//! Official orchard (0.15.5) test vectors, byte-identical proofs.
//!
//! Witness + instance + proof hex are embedded below (no files), exported
//! from official `my_test`/`export_fixed_v3` with ChaCha seed `[12; 32]`
//! (`DRAWS_AFTER_WITNESS=2444`, official self-verify `true`).
//!
//! Run with:
//! `cargo test --release -p blockchain-utils --features orchard-halo2 --test kats orchard_official_vectors`
//! (debug-mode proving is very slow; use `--release`).

#![cfg(feature = "orchard-halo2")]

use blockchain_utils::encoding::hex::{decode, encode};
use blockchain_utils::zk::orchard_halo2::crypto_context::DefaultCryptoContext;
use blockchain_utils::zk::orchard_halo2::curve::PallasAffine;
use blockchain_utils::zk::orchard_halo2::field::{PallasFp, VestaFq};
use blockchain_utils::zk::orchard_halo2::orchard::circuit::{
    OrchardCircuit, OrchardProtocolVersion,
};
use blockchain_utils::zk::orchard_halo2::orchard::prover::{
    DefaultOrchardProver, OrchardBatchProofInputs, OrchardBatchProofParams,
};
use blockchain_utils::zk::orchard_halo2::proof::verifier::PlonkVerifier;
use blockchain_utils::zk::orchard_halo2::rng::ChaChaBlindRng;

fn le_hex(s: &str) -> [u8; 32] {
    let h = s.strip_prefix("0x").unwrap_or(s);
    let b = decode(h).expect("hex");
    assert_eq!(b.len(), 32);
    let mut le = [0u8; 32];
    for (i, byte) in b.iter().rev().enumerate() {
        le[i] = *byte;
    }
    le
}

fn fp(s: &str) -> PallasFp {
    PallasFp::from_le_array(&le_hex(s)).unwrap()
}

fn fq(s: &str) -> VestaFq {
    VestaFq::from_le_array(&le_hex(s)).unwrap()
}

fn aff(xy: &str) -> PallasAffine {
    let mut it = xy.split(',');
    let x = le_hex(it.next().unwrap());
    let y = le_hex(it.next().unwrap());
    PallasAffine::from_le_xy(x, y).unwrap()
}

// Test helper mirrors the upstream vector columns one-to-one; packing them
// into a struct would hide the column mapping, so the arity lint is allowed.
#[allow(clippy::too_many_arguments)]
fn prove_and_match(
    version: OrchardProtocolVersion,
    path: &[&str],
    pos: usize,
    gd_old: &str,
    pkd_old: &str,
    v_old: u64,
    rho_old: &str,
    psi_old: &str,
    rcm_old: &str,
    cm_old: &str,
    alpha: &str,
    ak: &str,
    nk: &str,
    rivk: &str,
    gd_new: &str,
    pkd_new: &str,
    v_new: u64,
    psi_new: &str,
    rcm_new: &str,
    rcv: &str,
    inst: &[&str],
    proof_hex: &str,
) {
    let circuit = OrchardCircuit {
        path: Some(path.iter().map(|s| fp(s)).collect()),
        pos: Some(pos),
        gd_old: Some(aff(gd_old)),
        pkd_old: Some(aff(pkd_old)),
        v_old: Some(v_old),
        rho_old: Some(fp(rho_old)),
        psi_old: Some(fp(psi_old)),
        rcm_old: Some(fq(rcm_old)),
        cm_old: Some(aff(cm_old)),
        alpha: Some(fq(alpha)),
        ak: Some(aff(ak)),
        nk: Some(fp(nk)),
        rivk: Some(fq(rivk)),
        gd_new: Some(aff(gd_new)),
        pkd_new: Some(aff(pkd_new)),
        v_new: Some(v_new),
        psi_new: Some(fp(psi_new)),
        rcm_new: Some(fq(rcm_new)),
        rcv: Some(fq(rcv)),
        version,
    };
    let column: Vec<PallasFp> = inst.iter().map(|s| fp(s)).collect();
    assert_eq!(column.len(), 10);
    let columns: Vec<Vec<PallasFp>> = vec![column];
    let ctx = DefaultCryptoContext;
    let prover = DefaultOrchardProver::build(&ctx, version, 11).unwrap();
    let mut rng = ChaChaBlindRng::from_seed(&[12u8; 32]);
    rng.skip_bytes(2444);
    let args = OrchardBatchProofParams {
        args: vec![OrchardBatchProofInputs {
            circuit,
            instance: columns.clone(),
        }],
    };
    let proof = prover.create_orchard_proof(&args, &mut rng).unwrap();
    let hex: String = encode(&proof);
    assert_eq!(hex, proof_hex, "proof bytes differ from official");
    assert_eq!(proof.len(), 4992);
    // Verify both our proof and the embedded official proof.
    let v = PlonkVerifier::with_keys(
        prover.prover.params.clone(),
        prover.prover.proving_key.vk.clone(),
    );
    let inst3: Vec<Vec<Vec<PallasFp>>> = vec![columns.clone()];
    assert!(v.verify_sync(&proof, &inst3).unwrap());
    let official = decode(proof_hex).expect("hex");
    assert!(v.verify_sync(&official, &inst3).unwrap());
}

